          properties: {query: {type: 'string'}},
          required: ['query'],
        },
      },
      async input => {
        seenInputs.push(input);
        return `found:${String(input.query)}`;
      }
    );

    const observedToolResults: string[] = [];
    let callIndex = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        callIndex += 1;
        if (callIndex === 1) {
          yield {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}};
          yield STOP_FOR_TOOL;
          return;
        }
        const last = params.messages[params.messages.length - 1];
        const parts = Array.isArray(last?.content) ? last.content : [];
        const results = parts
          .filter((part): part is ToolResultContent => part.type === 'tool_result')
          .map(part => part.content);
        observedToolResults.push(...results);
        if (callIndex === 2) {
          yield {type: 'tool_use', toolCall: {id: 'c2', name: 'lookup', input: {query: 'hal'}}};
          yield STOP_FOR_TOOL;
          return;
